        File(dir, ".claude-plugin").takeIf { it.isDirectory }?.let { searchDirs.add(it) }
        for (sd in searchDirs) {
            val mcpFile = File(sd, ".mcp.json").takeIf { it.isFile } ?: continue
            return try {
                val obj = json.decodeFromString<JsonObject>(mcpFile.readText())
                val servers = obj["mcpServers"]?.jsonObject ?: return emptyList()
                servers.entries.map { (name, value) ->
                    val cfg = value.jsonObject
                    McpServerDef(name, cfg["command"]?.jsonPrimitive?.content ?: "", cfg["url"]?.jsonPrimitive?.content ?: "", cfg["transport"]?.jsonPrimitive?.content ?: "stdio")
                }
            } catch (e: Exception) {
                Log.w(TAG, "Failed to parse .mcp.json: ${e.message}")
                emptyList()
            }
        }
        return emptyList()
    }
